import React, { KeyboardEvent } from 'react';
import classNames from 'classnames';

import './index.less';

export interface NumberPickerProps {
  onNumberPicked: (number: number) => void;
  className?: string;
  start: number;
  end: number;
  interval?: number;
  leadingZero?: boolean;
  value?: number;
  onKeyDown?: (event: KeyboardEvent<HTMLElement>) => void;
}

function NumberPicker({
  start,
  end,
  interval = 1,
  className,
  onNumberPicked,
  leadingZero,
  value,
  onKeyDown,
}: NumberPickerProps) {
  const length = (end - start + 1) / interval;

  const formatNumber = (number) => (leadingZero && number < 10 ? `0${number}` : number);
  return (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
    <div role="group" className={classNames('number-picker', className)} onKeyDown={onKeyDown}>
      {[...new Array(length)].map((_, index) => {
        const number = start + index * interval;

        return (
          <button
            key={`number_${number}`}
            className={classNames('number-picker__number', {
              selected: value === number,
            })}
            type="button"
            onClick={() => onNumberPicked(number)}
          >
            {formatNumber(number)}
          </button>
        );
      })}
    </div>
  );
}

export default NumberPicker;
